#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int T;    cin >> T;    while (T--) {        int n;        string s;        cin >> n >> s;         string t = s;        sort(t.begin(), t.end());         if (s == t) {            cout << "Bob\n";            continue;        }         vector<int> idx;        for (int i = 0; i < n; i++) {            if (s[i] != t[i]) {                idx.push_back(i + 1);            }        }         cout << "Alice\n";        cout << idx.size() << '\n';        for (int i = 0; i < (int)idx.size(); i++) {            if (i) cout << ' ';            cout << idx[i];        }        cout << '\n';    }     return 0;}